void* AllocateNonPagedPoolWithHeader(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Add size of the header
    size_t totalSize = sizeof(size_t) + size;
    void* pool = ExAllocatePoolWithTag(NonPagedPool, totalSize, 'POOL');

    if (pool == NULL) {
