void* AllocateNonPagedPoolWithHeader(size_t size) {
    // Check that the requested size is non-zero
    if (size == 0) {
        return NULL;
    }

    // Calculate the total size needed for the allocation (header + data)
    size_t totalSize = sizeof(size_t) + size;

    // Allocate memory from the NonPagedPool with a tag
    void* allocatedBlock = ExAllocatePoolWithTag(NonPagedPool, totalSize, 'HDRP');

    if (allocatedBlock == NULL) {
        // Allocation failed
        return NULL;
    }

    // Store the size in the header (before the data portion)
    size_t* header = (size_t*)allocatedBlock;
    *header = size;

    // Return a pointer to the data portion of the block
    return (void*)(header + 1);
}
